mapper.select:
select distinct re.id,re.SYNC_STATUS, re.CHECK_MONTH, re.SHOULD_ON, re.ACTUAL_ON,RE.BLANK,
re.badge,st.comp_Id,
re.STANDARD, re.ACCOUNT, re.RECHARGE_TYPE ,st.create_time, st.dep_name, st.comp_name, st.name,
st.WELFARE_LEVEL||'-'||st.JCHE_NAME as welfareLevel
from smt_staff_recharge re
left join smt_staff st on st.badge = re.badge
left join smt_park_bu spb on st.comp_id = spb.comp_id


		AND ST.NAME LIKE CONCAT(CONCAT('%',#{query.name}),'%')


		AND re.RECHARGE_TYPE = #{query.rechargeType}


		AND re.badge = #{query.badges}


		AND re.CHECK_MONTH = #{query.checkMonth}


		AND ST.DEP_ID = #{query.depId}


		AND re.SYNC_STATUS = #{query.syncStatus}


		AND ST.COMP_ID = #{query.compId}


		AND ST.COMP_ID IN

			#{tempId}



		AND SPB.PARK_ID = #{query.parkId}


		AND st.create_time BETWEEN to_date(#{query.startEntryTime},'yyyy-mm-dd') and
		to_date(#{query.endEntryTime},'yyyy-mm-dd')


		AND SPB.PARK_ID IN

			#{tempId}



		AND re.badge IN

			#{badge}



		AND re.ACCOUNT = 0


		AND re.ACCOUNT != 0


order by re.CHECK_MONTH desc

